export const calculateSurvivalRate = (initial, current) => {
    // Pastikan kita bekerja dengan angka, ganti koma dengan titik jika user input format Indonesia
    const initialNum = parseFloat(String(initial).replace(',', '.'));
    const currentNum = parseFloat(String(current).replace(',', '.'));
    
    // 1. Jika kolom minggu ini kosong, jangan tampilkan persentase (tampilkan PENDING/null)
    if (current === "" || current === null || current === undefined || isNaN(currentNum)) {
        return null;
    }
    
    // 2. Jika Initial Fragments belum diisi atau nol, jangan paksa jadi 0%, kembalikan null
    // agar tidak merusak rata-rata grafik.
    if (!initialNum || initialNum === 0 || isNaN(initialNum)) {
        return null; 
    }
    
    // 3. Hitung Rate
    const rate = (currentNum / initialNum) * 100;
    
    // Batasi agar tidak lebih dari 100% (opsional, tapi bagus untuk data lapangan)
    // dan pastikan hanya ada 2 angka di belakang koma
    return parseFloat(Math.min(rate, 100).toFixed(2));
};

export const getStatusConfig = (sr) => {
    // Jika sr adalah null (data belum diisi), tampilkan PENDING
    if (sr === null || sr === undefined) {
        return { label: 'PENDING', color: '#bdc3c7' };
    }
    
    // Thresholds
    if (sr >= 75) return { label: 'VERY GOOD', color: '#27ae60' };
    if (sr >= 50) return { label: 'GOOD', color: '#3498db' }; 
    if (sr >= 45) return { label: 'BAD', color: '#f39c12' };
    return { label: 'VERY BAD', color: '#e74c3c' };
};